// If a section is lowered, hide its mesh and drop every zone.
// ScMapPitchDown registers the zones again the next time it runs.
MapReset <- function ()
{
	if (isPitchDown == 1)
	{
		local hMap = CMND_GET_MAP_HANDLE();
		CMND_SET_MAP_MESH_VISIBLE(hMap, mapMesh[nowIdx], 0, 0);
		CMND_BTL_ALL_RESET_FLOOR();
		execTimer = 0;
		isPitchDown = 0;
	}
};
